import{_ as n,C as e,o as s,c as d,E as a,a5 as l}from"./chunks/framework.DOB-AMqW.js";const b=JSON.parse('{"title":"Flowra Privacy Policy","description":"Privacy Policy for the Flowra application, presented within Policy Hub.","frontmatter":{"title":"Flowra Privacy Policy","description":"Privacy Policy for the Flowra application, presented within Policy Hub."},"headers":[],"relativePath":"apps/flowra/privacy.md","filePath":"apps/flowra/privacy.md"}'),c={name:"apps/flowra/privacy.md"};function p(h,o,u,y,m,f){const r=e("AppBreadcrumbs"),t=e("AppSubnav"),i=e("CopyStandaloneUrl");return s(),d("div",null,[a(r,{"app-id":"flowra",current:"Privacy Policy"}),a(t,{"app-id":"flowra"}),a(i,{path:"/privacy/flowra",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"Flowra privacy policy"}),o[0]||(o[0]=l('<h1 id="privacy-policy-for-flowra" tabindex="-1">Privacy Policy for Flowra <a class="header-anchor" href="#privacy-policy-for-flowra" aria-label="Permalink to &quot;Privacy Policy for Flowra&quot;">​</a></h1><p><strong>Effective Date:</strong> August 19, 2026<br><strong>Last Updated:</strong> August 19, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Flowra is a private, offline-first period and cycle tracker developed by <strong>Anand Raja</strong>. It supports separate profiles, daily menstrual-health logs, on-device cycle estimates, optional local reminders, and user-controlled exports and backups.</p><p>Flowra does not require an account and does not include advertising, analytics, tracking, crash reporting, or developer-operated cloud sync. The developer does not receive the health information entered into the app.</p><p>Flowra provides record keeping and descriptive estimates only. It is not a medical service and does not diagnose, prevent, or treat a health condition.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>Depending on what you choose to enter, Flowra may store:</p><ul><li>Profile names or nicknames, relationship, optional notes, and privacy settings</li><li>Optional age information, such as date of birth, birth year, approximate age, or age range</li><li>Whether menstruation has started and optional first-period date, year, or age</li><li>A user-selected reproductive life stage</li><li>Period start and end dates and whether a record is excluded from predictions</li><li>Daily flow, menstrual products, symptoms and severity, moods, overall mood, and private notes</li><li>On-device predictions, cycle statistics, and prediction accuracy history</li><li>Reminder timing and notification privacy preferences</li><li>Theme, language, PIN, biometric, screenshot, and app-lock settings</li></ul><p>You control which optional details to enter. Exact dates of birth and first-period dates are not required.</p><h2 id="local-storage-and-security" tabindex="-1">Local Storage and Security <a class="header-anchor" href="#local-storage-and-security" aria-label="Permalink to &quot;Local Storage and Security&quot;">​</a></h2><p>On Android, records are stored in a SQLite database within Flowra&#39;s private app storage. The SQLite database is not encrypted at the database level. Android&#39;s application sandbox restricts ordinary access by other apps, and Flowra disables Android cloud backup and device-transfer backup for its private files and databases.</p><p>In the browser version, records are encrypted with AES-GCM before being stored in IndexedDB. The non-exportable encryption key is retained in the same browser origin. Clearing that site&#39;s browser data removes both the encrypted records and the key required to read them.</p><p>An optional app PIN locks the Flowra interface. Flowra stores a salted PBKDF2 verifier rather than the PIN itself in its normal app settings. The app PIN does not encrypt the Android SQLite database.</p><p>On supported Android devices, optional biometric unlock uses Android&#39;s strong biometric prompt and Android Keystore. An encrypted PIN credential and its initialization data are kept in private Android preferences; the key requires successful biometric authentication and is invalidated when biometric enrollment changes. Flowra does not receive fingerprint, face, or other biometric templates.</p><p>Optional screenshot blocking and recent-app preview protection use Android secure-window controls. Their availability can vary by Android version and device.</p><h2 id="predictions-and-health-information" tabindex="-1">Predictions and Health Information <a class="header-anchor" href="#predictions-and-health-information" aria-label="Permalink to &quot;Predictions and Health Information&quot;">​</a></h2><p>Cycle estimates and statistics are calculated locally from the records in the selected profile. They are uncertain estimates, not guarantees or diagnoses. Flowra does not send cycle history to a remote prediction or artificial intelligence service.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>If you enable period reminders on Android, Flowra requests notification permission and schedules notifications locally on the device. Private wording shows a general health reminder. If private wording is disabled, a notification may show the profile name and estimated timing on the lock screen or notification panel, subject to device settings.</p><h2 id="exports-backup-and-restore" tabindex="-1">Exports, Backup, and Restore <a class="header-anchor" href="#exports-backup-and-restore" aria-label="Permalink to &quot;Exports, Backup, and Restore&quot;">​</a></h2><p>Flowra can export period history as a CSV file and can open a printable report that you may save as PDF. These exports are not automatically encrypted. Anyone with access to an exported file may be able to read it.</p><p>When you create a Flowra backup, profiles, periods, daily logs, app settings, reminder settings, and prediction records are encrypted with AES-GCM using a key derived from your backup password with PBKDF2-SHA-256. Flowra does not store or recover that password. On Android, the backup is written to the Documents location; in a browser, it is downloaded to the location selected by the browser. Restoring a selected backup replaces the app&#39;s local records after the backup is decrypted and validated.</p><p>Flowra does not automatically upload exports or backups. You are responsible for protecting and deleting files you save, copy, or share.</p><h2 id="network-requests-and-third-parties" tabindex="-1">Network Requests and Third Parties <a class="header-anchor" href="#network-requests-and-third-parties" aria-label="Permalink to &quot;Network Requests and Third Parties&quot;">​</a></h2><p>The reviewed app contains no developer API, advertising SDK, analytics SDK, cloud database, remote prediction service, or third-party sign-in. Core tracking, prediction, reminder, security, export, and backup features operate without a developer server.</p><p>The optional browser version is delivered by its web host. That host may process ordinary connection information, such as an IP address, browser user agent, request time, and requested files, under the host&#39;s own terms and privacy policy. This delivery information is not the menstrual-health content stored by Flowra in the browser.</p><h2 id="device-permissions" tabindex="-1">Device Permissions <a class="header-anchor" href="#device-permissions" aria-label="Permalink to &quot;Device Permissions&quot;">​</a></h2><p>The Android build uses:</p><ul><li><strong>Notifications:</strong> requested only when you enable local reminders</li><li><strong>Biometric and fingerprint compatibility permissions:</strong> used only for optional strong-biometric unlock</li></ul><p>The reviewed source does not request camera, microphone, precise or approximate location, contacts, phone, call-log, SMS, calendar, or advertising-identifier access.</p><h2 id="data-sharing" tabindex="-1">Data Sharing <a class="header-anchor" href="#data-sharing" aria-label="Permalink to &quot;Data Sharing&quot;">​</a></h2><p>Flowra does not sell health or personal information. The developer does not receive or share the profiles, periods, symptoms, moods, notes, predictions, or settings stored by the app. Information leaves app-controlled storage only when you choose to export, print, back up, share a file, use a storage provider, or contact support.</p><p>If you email the developer, the information you include is used only to respond to your request and related support, privacy, or legal matters.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Local records remain until they are replaced by a restored backup, cleared through Android or browser storage settings, or removed by uninstalling the app. Exported CSV or PDF files and <code>.flowra</code> backups remain wherever you saved or shared them and must be deleted separately.</p><p>Flowra has no user account or developer-operated cloud database, so there is no server-side Flowra account data to request for deletion.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>Flowra can be used by a parent or caregiver to maintain an independent profile for someone they care for. The app does not knowingly transmit children&#39;s data to the developer. A parent or guardian should supervise use by a child, enter only information needed for personal tracking, and protect the device and any exported files.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>This policy may be updated when Flowra&#39;s features or data practices change. The effective and last-updated dates will be revised when changes are published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>For privacy questions about Flowra, contact:</p><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',44))])}const g=n(c,[["render",p]]);export{b as __pageData,g as default};
